# Mock the available tools since we're creating a self-contained implementation
class physics_engine:
    """Numerical integration library for solving differential equations"""

    @staticmethod
    def integrate(f: callable, initial_values: dict, t_min: float, t_max: float, dt: float = 0.01):
        """
        Perform forward Euler integration with the given function and parameters.
        """
        state = initial_values.copy()
        t = t_min
        results = []

        while t <= t_max:
            results.append({"time": t, **state})
            # Calculate derivatives at current state
            dydt = f(t, state)
            # Update state using Euler's method
            for key, value in dydt.items():
                state[key] += value * dt
            t += dt

        return results

    @staticmethod
    def rk4(f: callable, state: dict, t: float, dt: float) -> dict:
        """
        Runge-Kutta 4th order integration step for improved accuracy.
        """
        def add_dicts(d1, d2):
            return {k: d1[k] + d2[k] for k in d1.keys()}

        def scale_dict(d, scale):
            return {k: d[k] * scale for k in d.keys()}

        k1 = scale_dict(f(t, state), dt)
        k2 = scale_dict(f(t + dt/2, add_dicts(state, scale_dict(k1, 0.5))), dt)
        k3 = scale_dict(f(t + dt/2, add_dicts(state, scale_dict(k2, 0.5))), dt)
        k4 = scale_dict(f(t + dt, add_dicts(state, scale_dict(k3, 1))), dt)

        result = state.copy()
        for key in state.keys():
            result[key] += (k1[key] + 2*k2[key] + 2*k3[key] + k4[key]) / 6
        return dict(add_dicts(result, scale_dict(k1, 1/6)))
