class math_library:
    """Advanced mathematical functions including vector operations, calculus, and analytical geometry"""

    @staticmethod
    def magnitude(vector: dict):
        """Calculate the magnitude of a vector represented as a dictionary."""
        return math.sqrt(sum(v**2 for v in vector.values()))

    @staticmethod
    def distance(pos1: dict, pos2: dict) -> float:
        """Calculate the distance between two points in 3D space."""
        dx = pos1.get("x", 0) - pos2.get("x", 0)
        dy = pos1.get("y", 0) - pos2.get("y", 0)
        dz = pos1.get("z", 0) - pos2.get("z", 0)
        return math.sqrt(dx**2 + dy**2 + dz**2)

    @staticmethod
    def normalize(vector: dict) -> dict:
        """Normalize a vector to unit length."""
        mag = math_library.magnitude(vector)
        if mag == 0:
            return {k: 0 for k in vector.keys()}
        return {k: v/mag for k, v in vector.items()}

    @staticmethod
    def cross_product(a: dict, b: dict) -> dict:
        """Calculate the cross product of two 3D vectors."""
        return {
            "x": a["y"]*b["z"] - a["z"]*b["y"],
            "y": a["z"]*b["x"] - a["x"]*b["z"],
            "z": a["x"]*b["y"] - a["y"]*b["x"]
        }

    @staticmethod
    def dot_product(a: dict, b: dict) -> float:
        """Calculate the dot product of two vectors."""
        return a.get("x", 0)*b.get("x", 0) + a.get("y", 0)*b.get("y", 0) + a.get("z", 0)*b.get("z", 0)
