@dataclass
class CelestialBody:
    """Represents a celestial body in the solar system."""
    name: str
    mass:  # kg (example: Earth = 5.97 × 10^24 kg)
    pos: dict
    vel: dict
    radius_km: float = 0  # Physical radius for visualization only

    def __post_init__(self):
        # Ensure state dictionaries have default values if not provided
        if self.pos is None:
            self.pos = {"x": 0, "y": 0, "z": 0}
        if self.vel is None:
            self.vel = {"x": 0, "y": 0, "z": 0}

        # Add trackable state history for visualization and analysis
        self._trajectory: list = []
        self._state_history: list = []

    def record_state(self, time: float):
        """Record the current state for trajectory visualization."""
        self._trajectory.append({
            "time": time,
            "position": self.pos.copy()
        })
        self._state_history.append({
            "time": time,
            "position": self.pos.copy(),
            "velocity": self.vel.copy(),
            "kinetic_energy": self.kinetic_energy(),
            "potential_energy": None  # Will be set by the simulation
        })

    def calculate_acceleration(self, sun_mass: float = 1.989e30, G: float = 6.674e-11) -> dict:
        """
        Calculate the gravitational acceleration from the Sun at the current position.
        Uses the inverse cube law: F = G(m₁m₂)/r³
        """
        # Vector from sun to planet
        r_vec = {
            "x": self.pos["x"],
            "y": self.pos["y"],
            "z": self.pos["z"]
        }

        # Calculate distance
        r = math_library.magnitude(r_vec)
        if r == 0:
            raise ValueError("Cannot calculate acceleration at the sun's center (r=0)")

        # Unit vector pointing toward the Sun
        r_hat = math_library.normalize(r_vec)

        # Calculate gravitational force per unit mass (acceleration)
        # a = F/m = G*M_sun/r^3 * r_hat
        acceleration_magnitude = (G * sun_mass) / (r**3)

        # Calculate the acceleration vector (pointing toward the Sun)
        return {
            "x": -acceleration_magnitude * r_hat["x"],
            "y": -acceleration_magnitude * r_hat["y"],
            "z": -acceleration_magnitude * r_hat["z"]
        }

    def kinetic_energy(self) -> float:
        """Calculate the kinetic energy of the planet."""
        speed = math_library.magnitude(self.vel)
        return 0.5 * self.mass * speed**2

    def potential_energy(self, sun_mass: float, G: float = 6.674e-11) -> float:
        """Calculate the gravitational potential energy relative to the Sun."""
        r = math_library.magnitude(self.pos)
        if r == 0:
            return float('inf')
        return -G * self.mass * sun_mass / r
