// ============================================================================

class CelestialBody
{
public:
    std::string name;        // Human-readable name
    double mass;             // Mass in solar masses
    Vector3d position;       // Current position (AU)
    Vector3d velocity;       // Current velocity (AU/year)

    // Constructor
    CelestialBody() : mass(0), position(0, 0, 0), velocity(0, 0, 0) {}

    CelestialBody(const std::string& name, double mass, 
                  Vector3d position, Vector3d velocity)
        : name(name), mass(mass), position(position), velocity(velocity) {}

    // Calculate gravitational force between this body and another
    Vector3d calculateGravitationalForce(const CelestialBody& other) const
    {
        // Newton's inverse cube law: F = G*m1*m2/r^3
        // The gravitational force is proportional to the product of masses
        // and inversely proportional to the cube of the distance

        Vector3d delta = other.position - position;
        double distance_squared = delta.dot(delta);
        double distance = std::sqrt(distance_squared);

        // Avoid division by zero and extremely small distances
        if (distance < 1.0e-8) {
            return Vector3d(0, 0, 0);
        }

        double distance_cubed = distance * distance * distance;

        // The direction of force is along the line connecting the two bodies
        Vector3d n = delta.normalize();  // Unit vector pointing from this to other

        // Calculate force magnitude using F = G*m1*m2/r^3
        double force_magnitude = constants::G * mass * other.mass / distance_cubed;

        // Final force vector
        return n * force_magnitude;
    }

    // Calculate gravitational acceleration exerted by other bodies
    Vector3d calculateAcceleration(const std::vector<CelestialBody>& bodies) const
    {
        Vector3d totalForce(0, 0, 0);

        for (const auto& body : bodies) {
            if (&body != this) {
                totalForce = totalForce + calculateGravitationalForce(body);
            }
        }

        // Acceleration = Force / mass (from F = ma)
        if (std::fabs(mass) > constants::TOLERANCE) {
            return totalForce / mass;
        }

        return Vector3d(0, 0, 0);
    }

    // Print body information
    void printInfo() const {
        std::cout << name << ": mass=" << mass << 
                  " solar_masses, pos=(" << position.x << ", " <<
                  position.y << ", " << position.z << ") AU, " <<
                  "vel=(" << velocity.x * 206.265 / constants::YEAR_IN_DAYS << ", " <<
                  velocity.y * 206.265 / constants::YEAR_IN_DAYS << ", " <<
                  velocity.z * 206.265 / constants::YEAR_IN_DAYS << ") km/s" << endl;
    }
};

